import React, { useEffect, useState } from "react";

function Dashboard() {
  const [responseData, setResponseData] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  const loginPayload = {
    userid: "jay",
    password: "jay123",
  };

  useEffect(() => {
    const baseUrl = "https://novaoffice.novasoftwares.com/service.aspx";
    const queryParams = new URLSearchParams({
      ApiVer: "1",
      Devid: "online",
      AppId: "NV01",
      Lat: "0",
      Lng: "0",
      Control: "auth",
      data: encodeURIComponent(JSON.stringify(loginPayload)),
    });

    const fullUrl = `${baseUrl}?${queryParams.toString()}`;

    fetch(fullUrl)
      .then((res) => {
        if (!res.ok) throw new Error("Failed to fetch");
        return res.json();
      })
      .then((data) => {
        setResponseData(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching:", err);
        setError("Something went wrong while fetching the API.");
        setLoading(false);
      });
  }, []);

  return (
    <div
      style={{
        padding: "2rem",
        background: "#f0f4f8",
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "flex-start",
      }}
    >
      <div
        style={{
          background: "white",
          padding: "2rem",
          borderRadius: "16px",
          boxShadow: "0 0 20px rgba(0,0,0,0.1)",
          width: "100%",
          maxWidth: "700px",
        }}
      >
        <h2>Fetched Data</h2>
        {loading && <p>Loading...</p>}
        {error && <p style={{ color: "red" }}>{error}</p>}
        {responseData && (
          <pre
            style={{
              background: "#eee",
              padding: "1rem",
              borderRadius: "10px",
              overflowX: "auto",
            }}
          >
            {JSON.stringify(responseData, null, 2)}
          </pre>
        )}
      </div>
    </div>
  );
}

export default Dashboard;
